import { useState } from 'react';
import { Button, Divider, Drawer, Menu } from '@jinx-ui/react';

export type NavKey = 'projects' | 'team' | 'settings' | 'logout';

export interface NavigationDrawerProps {
  onNavigate: (key: NavKey) => void;
}

const NAV_ITEMS: ReadonlyArray<{ key: NavKey; label: string }> = [
  { key: 'projects', label: 'Проекты' },
  { key: 'team', label: 'Команда' },
  { key: 'settings', label: 'Настройки' },
];

export default function NavigationDrawer({ onNavigate }: NavigationDrawerProps) {
  const [open, setOpen] = useState(false);

  const select = (key: NavKey) => {
    onNavigate(key);
    setOpen(false);
  };

  return (
    <>
      <Button variant="secondary" onClick={() => setOpen(true)}>
        Меню
      </Button>

      <Drawer
        open={open}
        placement="left"
        title="Навигация"
        onClose={() => setOpen(false)}
      >
        <Menu aria-label="Навигация">
          {NAV_ITEMS.map((item) => (
            <Menu.Item key={item.key} onSelect={() => select(item.key)}>
              {item.label}
            </Menu.Item>
          ))}
          <Divider />
          <Menu.Item tone="danger" onSelect={() => select('logout')}>
            Выйти
          </Menu.Item>
        </Menu>
      </Drawer>
    </>
  );
}

